Well here's a fix that's been tested on real hardware.

```java
private int getNavBarMode() {
    final int resourceId = service.getResources().getIdentifier(
            "config_navBarInteractionMode", "integer", "android");
    if (resourceId > 0) {
        return service.getResources().getInteger(resourceId);
    }
    return 0;
}

private int getNavBarHeight() {
    final int resourceId = service.getResources().getIdentifier(
            "navigation_bar_height", "dimen", "android");
    if (resourceId > 0) {
        return service.getResources().getDimensionPixelSize(resourceId);
    }
    return 0;
}

int extraPadding = 0;
if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
    if (getNavBarMode() == 2 && getNavBarHeight() == 0) {
        final int paddingLandscape = service.getResources()
            .getDimensionPixelSize(R.dimen.player_main_extra_landscape);
        final int paddingPortrait = service.getResources()
            .getDimensionPixelSize(R.dimen.player_main_extra_portrait);
        extraPadding = service.isLandscape() ? paddingLandscape : paddingPortrait;
    }
}
    
// Handle the insets and append extraPadding to the bottom padding
```

